  patientId      String
  practitionerId String
  status         String
  notes          String?
  diagnosisCodes String    @default("[]")
  procedureCodes String    @default("[]")
  arrivedAt      DateTime
  startedAt      DateTime?
  completedAt    DateTime?
}

model BillingInvoice {
  id         String               @id
  payerId    String
  sourceType String
  sourceId   String
  status     String
  totalCents Int
  issuedAt   DateTime
  lines      BillingInvoiceLine[]

  @@unique([sourceType, sourceId])
}

model BillingInvoiceLine {
  id          String         @id
  invoiceId   String
