      clock.set(new Date('2026-03-02T08:00:00Z'));
      await scheduleAppointment('person-5', '2026-03-05T10:00:00.000Z', 'dr-wilson'); // attended or pending: not a no-show

      const response = await http()
        .get('/reports/no-shows')
        .query({ from: '2026-03-01', to: '2026-03-31' })
        .expect(200);

      expect(response.body).toEqual([
        { practitionerId: 'dr-house', noShows: 2, totalFeesCents: 20_000 },
        { practitionerId: 'dr-wilson', noShows: 1, totalFeesCents: 10_000 },
      ]);
    });

    it('includes the whole last day when "to" is a plain date', async () => {
      await noShow('person-1', '2026-03-31T22:00:00.000Z', 'dr-house');

      const response = await http().get('/reports/no-shows').query({ from: '2026-03-31', to: '2026-03-31' }).expect(200);

      expect(response.body).toEqual([{ practitionerId: 'dr-house', noShows: 1, totalFeesCents: 10_000 }]);
    });

    it('returns an empty list when there are no no-shows in the period', async () => {
      const response = await http().get('/reports/no-shows').query({ from: '2026-01-01', to: '2026-01-31' }).expect(200);

      expect(response.body).toEqual([]);
    });

    it.each([
      ['missing from', { to: '2026-03-31' }],
      ['missing to', { from: '2026-03-01' }],
      ['invalid date', { from: 'yesterday', to: '2026-03-31' }],
      ['from after to', { from: '2026-04-01', to: '2026-03-01' }],
    ])('rejects %s with 400', async (_name, query) => {
      await http().get('/reports/no-shows').query(query).expect(400);
    });
  });

